sections.code:
li[data-stock-level="low"] { color: #b45309; }

li::after {
  content: " · " attr(data-category);
  color: #6b7280;
}

#filter-panel[data-state="closed"] .options { display: none; }

/* clean for mouse, visible for keyboard */
:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

<button id="bold-btn">
  <span aria-hidden="true">B</span>
  <span class="sr-only">Bold</span>
</button>
